-- קבצי קורות החיים של שאול, כמו שהעלה אותם.
--
-- 13.11.2026, אחרי שפתח גרסה שהמחולל כתב למשרה: "זה לא טוב, אני צריך
-- את הקורות חיים המקוריים ששלחתי לך ואתה מצרף אותם לכל מייל לפי
-- הדרישה".
--
-- המחולל נבנה אחרי ש-ב-3.11 ארבע הגרסאות הראשונות יצאו כמעט זהות, והוא
-- תוקן כך שיבחר מהבסיס רק שורות שמשרתות את דרישות המודעה. התוצאה
-- קצרה מהבסיס בכוונה, ושאול לא רוצה אותה בפנייה למכר. בפנייה כזאת
-- הקובץ עובר הלאה פנימית, ושם קורות חיים מלאים עדיפים.
--
-- לכן הקבצים נשמרים כאן, והשליחה מצרפת אותם לפי משפחת התפקידים.
-- בדלי ציבורי הם לא יושבים: המסך מוגן לפי בעלים, והם לא בכתובת
-- פומבית שאפשר לסרוק.
--
-- עדכון קובץ בעתיד: שאול מעלה גרסה חדשה בצ'אט ומיגרציה כזאת נכתבת שוב.

alter table cvs add column if not exists pdf_base64 text;
alter table cvs add column if not exists filename text;


update cvs set pdf_base64 = '', filename = 'Shaul_Mano_QA_Manager.pdf' where id = 'qa';

update cvs set pdf_base64 = '', filename = 'Shaul_Mano_Project_Manager.pdf' where id = 'program';

update cvs set pdf_base64 = '', filename = 'Shaul_Mano_Project_Release_Manager.pdf' where id = 'project-release-manager';

