-- Delivery מעודכן, והקובץ של פרויקטים ושחרורים מכסה גם את המשפחה
-- הזאת. הגרסה delivery נשארת לצורך הניקוד, כדי שמשרות Service
-- Delivery Manager ימשיכו להיתפס, ורק הקובץ שלה מוחלף.
update cvs set pdf_base64 = '', filename = 'Shaul_Mano_Project_Release_Manager.pdf' where id = 'delivery';

